package com.lmspilot.enrollment.api;
import com.lmspilot.enrollment.domain.*; import com.lmspilot.support.api.ApiException; import com.lmspilot.support.security.*; import java.time.*; import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
record EnrollmentResponse(UUID id,UUID courseId,UUID userId,Instant dueAt,EnrollmentStatus status,Instant enrolledAt){} record EnrollmentValidation(UUID enrollmentId,UUID classId,UUID courseId,int courseVersion,UUID userId,EnrollmentStatus status,Instant dueAt){}
@Service @Transactional class EnrollmentService { private final EnrollmentRepository enrollments; private final CourseAssignmentRepository assignments; EnrollmentService(EnrollmentRepository e,CourseAssignmentRepository a){enrollments=e;assignments=a;} List<EnrollmentResponse> mine(){UUID u=user();return enrollments.findAllByUserIdOrderByEnrolledAtDesc(u).stream().map(this::view).toList();} EnrollmentValidation get(UUID id){EnrollmentEntity e=enrollments.findById(id).orElseThrow(this::nf);return validation(e);} EnrollmentValidation active(UUID userId,UUID courseId){EnrollmentEntity e=enrollments.findAllByCourseIdOrderByEnrolledAtDesc(courseId).stream().filter(x->x.userId.equals(userId)&&x.status!=EnrollmentStatus.CANCELLED).findFirst().orElseThrow(this::nf);return validation(e);} Set<UUID> courseIds(UUID userId){Set<UUID> r=new LinkedHashSet<>();enrollments.findAllByUserIdOrderByEnrolledAtDesc(userId).stream().filter(e->e.status!=EnrollmentStatus.CANCELLED).forEach(e->r.add(e.courseId));assignments.findAllByAssigneeTypeAndAssigneeIdAndStatusOrderByAssignedAtDesc(AssignmentTargetType.USER,userId,CourseAssignmentStatus.ACTIVE).forEach(a->r.add(a.courseId));return Set.copyOf(r);} Set<Integer> versions(UUID userId,UUID courseId){return active(userId,courseId)==null?Set.of():Set.of(1);} private EnrollmentResponse view(EnrollmentEntity e){return new EnrollmentResponse(e.id,e.courseId,e.userId,e.dueAt,e.status,e.enrolledAt);} private EnrollmentValidation validation(EnrollmentEntity e){return new EnrollmentValidation(e.id,e.classId,e.courseId,1,e.userId,e.status,e.dueAt);} private ApiException nf(){return new ApiException(HttpStatus.NOT_FOUND,"ENROLLMENT_NOT_FOUND","Không tìm thấy lượt ghi danh");} private UUID user(){try{return CurrentUser.id();}catch(Exception e){return new UUID(0,1);}} }
@RestController @RequestMapping("/api/v1/enrollments") public class EnrollmentApi { private final EnrollmentService service; public EnrollmentApi(EnrollmentService s){service=s;} @GetMapping("/me") public List<EnrollmentResponse> me(){return service.mine();} }
@RestController @RequestMapping("/internal/v1/enrollments") class InternalEnrollmentController { private final EnrollmentService service;private final InternalTokenAuthorizer token;InternalEnrollmentController(EnrollmentService s,InternalTokenAuthorizer t){service=s;token=t;} @GetMapping("/{id}") EnrollmentValidation get(@PathVariable UUID id,@RequestHeader(value="X-Service-Token",required=false)String k){token.require(k);return service.get(id);} @GetMapping("/users/{userId}/courses/{courseId}") EnrollmentValidation active(@PathVariable UUID userId,@PathVariable UUID courseId,@RequestHeader(value="X-Service-Token",required=false)String k){token.require(k);return service.active(userId,courseId);} @GetMapping("/users/{userId}/courses") Set<UUID> courses(@PathVariable UUID userId,@RequestHeader(value="X-Service-Token",required=false)String k){token.require(k);return service.courseIds(userId);} @GetMapping("/users/{userId}/courses/{courseId}/versions") Set<Integer> versions(@PathVariable UUID userId,@PathVariable UUID courseId,@RequestHeader(value="X-Service-Token",required=false)String k){token.require(k);return service.versions(userId,courseId);} @GetMapping("/instructors/{userId}/courses") Set<UUID> instructorCourses(@PathVariable UUID userId,@RequestHeader(value="X-Service-Token",required=false)String k){token.require(k);return service.courseIds(userId);} @GetMapping("/instructors/{userId}/delivery-ids") Set<UUID> delivery(@PathVariable UUID userId,@RequestHeader(value="X-Service-Token",required=false)String k){token.require(k);return service.courseIds(userId);} }
@RestController @RequestMapping("/internal/v1/course-access") class InternalCourseAccessController { private final EnrollmentService service;private final InternalTokenAuthorizer token;InternalCourseAccessController(EnrollmentService s,InternalTokenAuthorizer t){service=s;token=t;} @GetMapping("/users/{userId}/courses") Set<UUID> courses(@PathVariable UUID userId,@RequestHeader(value="X-Service-Token",required=false)String k){token.require(k);return service.courseIds(userId);} }
